update consumable_store_stock
set num = num - #{param.num},
amount = amount - #{param.amount},
update_by = #{param.updateBy},
updater_id = #{param.updaterId},
updater_type = #{param.updaterType},
update_time = #{param.updateTime}
where store_id = #{param.storeId}
and consumable_id = #{param.consumableId}
and num >= #{param.num}
